SELECT order_id, CASE WHEN unit_price >= 330 THEN 'high' WHEN unit_price >= 110 THEN 'mid' ELSE 'low' END AS unit_price_bucket, ROUND(AVG(unit_price), 2) AS avg_unit_price FROM order_items WHERE NOT (order_id = 36 OR product_id IN (8, 16, 26, 31)) GROUP BY order_id, CASE WHEN unit_price >= 330 THEN 'high' WHEN unit_price >= 110 THEN 'mid' ELSE 'low' END HAVING ROUND(AVG(unit_price), 2) > 39 ORDER BY order_id DESC, unit_price_bucket
